@Serializable(with = QrLoginStatus.Serializer::class)
sealed interface QrLoginStatus {
    data object Starting : QrLoginStatus
    /** Show this QR code (base64 of its bytes) to the other device */
    @Serializable
    data class ShowQr(
        val data: String,
    ) : QrLoginStatus
    /** The other device scanned it: ask for the two digits it shows */
    data object EnterCheckCode : QrLoginStatus
    /** Show these two digits so they can be typed on the other device */
    @Serializable
    data class ShowCheckCode(
        val code: Long,
    ) : QrLoginStatus
    /** The other device has to approve; it may ask for this code */
    @Serializable
    data class WaitingForApproval(
        val user_code: String? = null,
    ) : QrLoginStatus
    /** Open this page to approve the new device, then call `confirm` */
    @Serializable
    data class ApproveInBrowser(
        val url: String,
    ) : QrLoginStatus
    data object SyncingSecrets : QrLoginStatus
    data object Done : QrLoginStatus

    object Serializer : JsonUnionSerializer<QrLoginStatus>("QrLoginStatus") {
        override fun read(json: JsonElement): QrLoginStatus = when (val tag = json.jsonObject["type"]?.jsonPrimitive?.content) {
            "starting" -> Starting
            "showQr" -> CoreJson.decodeFromJsonElement(ShowQr.serializer(), json)
            "enterCheckCode" -> EnterCheckCode
            "showCheckCode" -> CoreJson.decodeFromJsonElement(ShowCheckCode.serializer(), json)
            "waitingForApproval" -> CoreJson.decodeFromJsonElement(WaitingForApproval.serializer(), json)
            "approveInBrowser" -> CoreJson.decodeFromJsonElement(ApproveInBrowser.serializer(), json)
            "syncingSecrets" -> SyncingSecrets
            "done" -> Done
            else -> throw SerializationException("Unknown QrLoginStatus $tag")
        }

        override fun write(value: QrLoginStatus): JsonElement = when (value) {
            Starting -> tagged(JsonObject(emptyMap()), "type", "starting")
            is ShowQr -> tagged(CoreJson.encodeToJsonElement(ShowQr.serializer(), value), "type", "showQr")
            EnterCheckCode -> tagged(JsonObject(emptyMap()), "type", "enterCheckCode")
            is ShowCheckCode -> tagged(CoreJson.encodeToJsonElement(ShowCheckCode.serializer(), value), "type", "showCheckCode")
            is WaitingForApproval -> tagged(CoreJson.encodeToJsonElement(WaitingForApproval.serializer(), value), "type", "waitingForApproval")
            is ApproveInBrowser -> tagged(CoreJson.encodeToJsonElement(ApproveInBrowser.serializer(), value), "type", "approveInBrowser")
            SyncingSecrets -> tagged(JsonObject(emptyMap()), "type", "syncingSecrets")
            Done -> tagged(JsonObject(emptyMap()), "type", "done")
        }
    }
}

