/** The message a reply points at, as far as it's known yet */
@Serializable(with = ReplyPreview.Serializer::class)
sealed interface ReplyPreview {
    @Serializable
    data class Ready(
        val eventId: String,
        val sender: String,
        val senderName: String? = null,
        val summary: String,
        /** The replied-to message as far as it's known (formatting, media, decryption failure) */
        val content: EntryContent,
    ) : ReplyPreview
    /** Not loaded yet: call `loadReplyDetails(eventId)` */
    @Serializable
    data class Unavailable(
        val eventId: String,
    ) : ReplyPreview
    @Serializable
    data class Pending(
        val eventId: String,
    ) : ReplyPreview

    object Serializer : JsonUnionSerializer<ReplyPreview>("ReplyPreview") {
        override fun read(json: JsonElement): ReplyPreview = when (val tag = json.jsonObject["state"]?.jsonPrimitive?.content) {
            "ready" -> CoreJson.decodeFromJsonElement(Ready.serializer(), json)
            "unavailable" -> CoreJson.decodeFromJsonElement(Unavailable.serializer(), json)
            "pending" -> CoreJson.decodeFromJsonElement(Pending.serializer(), json)
            else -> throw SerializationException("Unknown ReplyPreview $tag")
        }

        override fun write(value: ReplyPreview): JsonElement = when (value) {
            is Ready -> tagged(CoreJson.encodeToJsonElement(Ready.serializer(), value), "state", "ready")
            is Unavailable -> tagged(CoreJson.encodeToJsonElement(Unavailable.serializer(), value), "state", "unavailable")
            is Pending -> tagged(CoreJson.encodeToJsonElement(Pending.serializer(), value), "state", "pending")
        }
    }
}

