/** Something that changed about the signed-in session */
@Serializable(with = SessionEvent.Serializer::class)
sealed interface SessionEvent {
    /** Tokens were refreshed: store the new session */
    @Serializable
    data class Refreshed(
        val session: Session,
    ) : SessionEvent
    /** The server no longer accepts the session (signed out elsewhere) */
    @Serializable
    data class Invalid(
        val softLogout: Boolean,
    ) : SessionEvent

    object Serializer : JsonUnionSerializer<SessionEvent>("SessionEvent") {
        override fun read(json: JsonElement): SessionEvent = when (val tag = json.jsonObject["type"]?.jsonPrimitive?.content) {
            "refreshed" -> CoreJson.decodeFromJsonElement(Refreshed.serializer(), json)
            "invalid" -> CoreJson.decodeFromJsonElement(Invalid.serializer(), json)
            else -> throw SerializationException("Unknown SessionEvent $tag")
        }

        override fun write(value: SessionEvent): JsonElement = when (value) {
            is Refreshed -> tagged(CoreJson.encodeToJsonElement(Refreshed.serializer(), value), "type", "refreshed")
            is Invalid -> tagged(CoreJson.encodeToJsonElement(Invalid.serializer(), value), "type", "invalid")
        }
    }
}

