/** One row of a room's timeline. */
@Serializable(with = TimelineEntry.Serializer::class)
sealed interface TimelineEntry {
    @Serializable
    data class Event(
        /** Stable across local echo -> remote event, use it as the UI key */
        val id: String,
        /** Identifies the event for actions (reply, edit, react, delete) */
        val itemKey: String,
        val eventId: String? = null,
        val sender: String,
        val senderName: String? = null,
        val senderAvatar: String? = null,
        /** Milliseconds since the Unix epoch */
        val timestamp: Long,
        val isOwn: Boolean,
        val isEditable: Boolean,
        val content: EntryContent,
        val inReplyTo: ReplyPreview? = null,
        val threadRoot: String? = null,
        /** Set on messages that started a thread */
        val thread: ThreadSummaryView? = null,
        val edited: Boolean,
        val reactions: List<Reaction>,
        val sendState: SendState? = null,
        /** Who has read up to here (their latest receipt is on this message) */
        val readBy: List<ReadReceiptView>,
        /** Intentional mentions (`m.mentions`) */
        val mentions: MentionsView? = null,
        /** Why sending failed, when `sendState` is `failed` */
        val sendError: String? = null,
    ) : TimelineEntry
    @Serializable
    data class DateDivider(
