/** Where a verification stands, flattened from the request and SAS state machines */
@Serializable(with = VerificationStatus.Serializer::class)
sealed interface VerificationStatus {
    /** Waiting for the other side to accept the request */
    data object Requested : VerificationStatus
    /** The other side asked to verify; call `accept()` */
    @Serializable
    data class Incoming(
        val otherUser: String,
        val isSelf: Boolean,
    ) : VerificationStatus
    /** Both sides are ready; the initiator calls `startSas()` */
    data object Ready : VerificationStatus
    /** The other side started comparing emojis; call `acceptSas()` */
    data object SasIncoming : VerificationStatus
    /** Comparing is being set up */
    data object SasStarted : VerificationStatus
    /** Compare these with the other device, then `confirm()` or `mismatch()` */
    @Serializable
    data class Emojis(
        val emojis: List<VerificationEmoji>,
        val decimals: List<Long>,
    ) : VerificationStatus
    /** Confirmed here, waiting for the other device */
    data object Confirmed : VerificationStatus
    data object Done : VerificationStatus
    @Serializable
    data class Cancelled(
        val reason: String,
        val byUs: Boolean,
    ) : VerificationStatus

    object Serializer : JsonUnionSerializer<VerificationStatus>("VerificationStatus") {
        override fun read(json: JsonElement): VerificationStatus = when (val tag = json.jsonObject["state"]?.jsonPrimitive?.content) {
            "requested" -> Requested
            "incoming" -> CoreJson.decodeFromJsonElement(Incoming.serializer(), json)
            "ready" -> Ready
            "sasIncoming" -> SasIncoming
            "sasStarted" -> SasStarted
            "emojis" -> CoreJson.decodeFromJsonElement(Emojis.serializer(), json)
            "confirmed" -> Confirmed
            "done" -> Done
            "cancelled" -> CoreJson.decodeFromJsonElement(Cancelled.serializer(), json)
            else -> throw SerializationException("Unknown VerificationStatus $tag")
        }

        override fun write(value: VerificationStatus): JsonElement = when (value) {
            Requested -> tagged(JsonObject(emptyMap()), "state", "requested")
            is Incoming -> tagged(CoreJson.encodeToJsonElement(Incoming.serializer(), value), "state", "incoming")
            Ready -> tagged(JsonObject(emptyMap()), "state", "ready")
            SasIncoming -> tagged(JsonObject(emptyMap()), "state", "sasIncoming")
            SasStarted -> tagged(JsonObject(emptyMap()), "state", "sasStarted")
            is Emojis -> tagged(CoreJson.encodeToJsonElement(Emojis.serializer(), value), "state", "emojis")
            Confirmed -> tagged(JsonObject(emptyMap()), "state", "confirmed")
            Done -> tagged(JsonObject(emptyMap()), "state", "done")
            is Cancelled -> tagged(CoreJson.encodeToJsonElement(Cancelled.serializer(), value), "state", "cancelled")
        }
    }
}

