@Serializable(with = RoomTimeline.Serializer::class)
class RoomTimeline(handle: Long, props: JsonObject) : Remote(handle, props) {
    object Serializer : RemoteSerializer<RoomTimeline>("RoomTimeline", ::RoomTimeline)

    /** Calls `listener` with timeline diffs, starting with a `reset` of the current items. */
    fun watch(listener: (List<ListDiff<TimelineEntry>>) -> Unit): Subscription =
        Runtime.watch("RoomTimeline.watch", handle, listOf(Arg.listener<List<ListDiff<TimelineEntry>>>(listener)), ::Subscription)

    /**
     * Loads older events; resolves `true` once the start of the room is reached.
     * Loads newer messages in a timeline opened at an event; true once at the latest.
     */
    suspend fun paginateForward(events: Long): Boolean =
        Runtime.call("RoomTimeline.paginateForward", handle, listOf(Arg.value<Long>(events)))

    suspend fun paginateBack(events: Long): Boolean =
        Runtime.call("RoomTimeline.paginateBack", handle, listOf(Arg.value<Long>(events)))

    /** Sends a text message (Markdown), as a reply when `replyTo` is an event ID. */
    suspend fun sendText(body: String, replyTo: String? = null) {
        Runtime.callUnit("RoomTimeline.sendText", handle, listOf(Arg.value<String>(body), Arg.value<String?>(replyTo)))
    }

    /** Sends ready-made HTML (custom emoji), as a reply when `replyTo` is set. */
    suspend fun sendHtml(body: String, html: String, replyTo: String? = null) {
        Runtime.callUnit("RoomTimeline.sendHtml", handle, listOf(Arg.value<String>(body), Arg.value<String>(html), Arg.value<String?>(replyTo)))
    }

    suspend fun sendSticker(body: String, url: String) {
        Runtime.callUnit("RoomTimeline.sendSticker", handle, listOf(Arg.value<String>(body), Arg.value<String>(url)))
    }

    suspend fun editText(itemKey: String, body: String, html: String? = null, mentions: Mentions? = null) {
        Runtime.callUnit("RoomTimeline.editText", handle, listOf(Arg.value<String>(itemKey), Arg.value<String>(body), Arg.value<String?>(html), Arg.value<Mentions?>(mentions)))
    }

    suspend fun editCaption(itemKey: String, caption: String, html: String? = null, mentions: Mentions? = null) {
        Runtime.callUnit("RoomTimeline.editCaption", handle, listOf(Arg.value<String>(itemKey), Arg.value<String>(caption), Arg.value<String?>(html), Arg.value<Mentions?>(mentions)))
    }

    suspend fun redact(itemKey: String, reason: String? = null) {
        Runtime.callUnit("RoomTimeline.redact", handle, listOf(Arg.value<String>(itemKey), Arg.value<String?>(reason)))
    }

    suspend fun toggleReaction(itemKey: String, key: String) {
        Runtime.callUnit("RoomTimeline.toggleReaction", handle, listOf(Arg.value<String>(itemKey), Arg.value<String>(key)))
    }

    suspend fun loadReplyDetails(eventId: String) {
        Runtime.callUnit("RoomTimeline.loadReplyDetails", handle, listOf(Arg.value<String>(eventId)))
    }

    /** Sends a text, emote or notice; without `html` the body is Markdown. */
    suspend fun sendMessage(kind: MessageKind, body: String, html: String? = null, replyTo: String? = null, mentions: Mentions? = null) {
        Runtime.callUnit("RoomTimeline.sendMessage", handle, listOf(Arg.value<MessageKind>(kind), Arg.value<String>(body), Arg.value<String?>(html), Arg.value<String?>(replyTo), Arg.value<Mentions?>(mentions)))
    }

    /** Sends any message-like event content with a local echo; `m.relates_to` is kept. */
    suspend fun sendEvent(eventType: String, content: JsonElement) {
        Runtime.callUnit("RoomTimeline.sendEvent", handle, listOf(Arg.value<String>(eventType), Arg.value<JsonElement>(content)))
    }

    /** Tries a failed message again. */
    suspend fun retrySend(itemKey: String) {
        Runtime.callUnit("RoomTimeline.retrySend", handle, listOf(Arg.value<String>(itemKey)))
    }

    /** Shares a location (`geo:lat,long`). */
    suspend fun sendLocation(body: String, geoUri: String, description: String? = null) {
        Runtime.callUnit("RoomTimeline.sendLocation", handle, listOf(Arg.value<String>(body), Arg.value<String>(geoUri), Arg.value<String?>(description)))
    }

    /** Uploads and sends a file with options (spoilers, voice messages). */
    suspend fun sendFile(bytes: Bytes, options: AttachmentOptions) {
        Runtime.callUnit("RoomTimeline.sendFile", handle, listOf(Arg.bytes(bytes), Arg.value<AttachmentOptions>(options)))
    }

    /**
     * Uploads a file for this room ahead of sending (encrypted in encrypted rooms);
     * `listener` gets the progress where the platform reports it. Resolves to the source
