    suspend fun sendUploaded(file: UploadedFile) {
        Runtime.callUnit("RoomTimeline.sendUploaded", handle, listOf(Arg.value<UploadedFile>(file)))
    }

    /** Starts a poll; `maxSelections` 1 makes it single-choice. */
    suspend fun sendPoll(question: String, answers: List<String>, maxSelections: Long, undisclosed: Boolean) {
        Runtime.callUnit("RoomTimeline.sendPoll", handle, listOf(Arg.value<String>(question), Arg.value<List<String>>(answers), Arg.value<Long>(maxSelections), Arg.value<Boolean>(undisclosed)))
