        Runtime.callUnit("RoomTimeline.vote", handle, listOf(Arg.value<String>(pollEventId), Arg.value<List<String>>(answers)))
    }

    suspend fun endPoll(pollEventId: String) {
        Runtime.callUnit("RoomTimeline.endPoll", handle, listOf(Arg.value<String>(pollEventId)))
    }

