        Runtime.callUnit("RoomTimeline.pin", handle, listOf(Arg.value<String>(eventId)))
    }

    suspend fun unpin(eventId: String) {
        Runtime.callUnit("RoomTimeline.unpin", handle, listOf(Arg.value<String>(eventId)))
    }

    suspend fun setTyping(typing: Boolean) {
        Runtime.callUnit("RoomTimeline.setTyping", handle, listOf(Arg.value<Boolean>(typing)))
    }

    /** Calls `listener` with the other users currently typing. */
    fun watchTyping(listener: (List<TypingUser>) -> Unit): Subscription =
        Runtime.watch("RoomTimeline.watchTyping", handle, listOf(Arg.listener<List<TypingUser>>(listener)), ::Subscription)

    /**
     * Marks the room read up to its latest message (unthreaded receipt and fully-read
     * marker); in a thread, a threaded and an unthreaded receipt. Private receipts aren't
     * shown to others.
     */
    suspend fun markAsRead(_private: Boolean? = null) {
        Runtime.callUnit("RoomTimeline.markAsRead", handle, listOf(Arg.value<Boolean?>(_private)))
    }
}

